<?php
// Admin team: the owner (config.php) adds colleagues by email; each colleague sets a password through a one-time link.
const STAFF_LINK_HOURS=72;
function staff_page(string $title,string $content):never{header('Content-Type: text/html; charset=utf-8');header('Cache-Control: private, no-store');echo str_replace('<main>','<main class="wide">',form_html($title,$content,'lt'));exit;}
function staff_link(string $email):string{sql("DELETE FROM rb_records WHERE kind='token' AND parent_id=?",['staff:'.$email]);$raw=bin2hex(random_bytes(32));$exp=time()+STAFF_LINK_HOURS*3600;put('token:'.secret_hash($raw),'token',['kind'=>'staff-password','email'=>$email,'expires'=>$exp],'staff:'.$email,'',$exp);return config()['public_url'].'/admin/password?t='.$raw;}
function staff_invite_mail(array $s,string $url,bool $reset):void{$who=config()['admin_email'];$text="Sveiki".($s['name']!==''?', '.$s['name']:'')."!\n\n".($reset?"Gavote naują nuorodą slaptažodžiui nustatyti":"{$who} pakvietė jus į Rundfunkbeitrag Support administravimą")." (".parse_url(config()['public_url'],PHP_URL_HOST).").\n\nAtidarykite nuorodą ir susikurkite slaptažodį:\n{$url}\n\nNuoroda galioja ".STAFF_LINK_HOURS." valandas ir tinka vieną kartą. Prisijungsite su šiuo el. pašto adresu: {$s['email']}\nJei šio laiško nelaukėte, tiesiog jį ištrinkite.";queue_mail(uuid(),['id'=>'staff'],'staff-invite',$s['email'],['subject'=>$reset?'Naujas slaptažodis administravimui':'Kvietimas į administravimą','text'=>$text]);}
function staff_save_owner_hash(string $hash):void{$c=config();$c['admin_hash']=$hash;$tmp=tempnam(private_root(),'.config-');chmod($tmp,0600);file_put_contents($tmp,"<?php\n// Private configuration. Never commit or expose this file.\nreturn ".var_export($c,true).";\n",LOCK_EX);if(!rename($tmp,private_root().'/config.php'))fail('CONFIG_WRITE_FAILED',503);if(function_exists('opcache_invalidate'))opcache_invalidate(private_root().'/config.php',true);}
function staff_new_password():string{$p=$_POST['password']??null;if(!is_string($p)||mb_strlen($p)<14)fail('Slaptažodis turi būti bent 14 simbolių.');if(strlen($p)>72)fail('Slaptažodis per ilgas (daugiausia 72 baitai).');if(!hash_equals($p,(string)($_POST['password2']??'')))fail('Slaptažodžiai nesutampa.');return password_hash($p,PASSWORD_DEFAULT);}
function staff_error(Throwable $e):string{if(!$e instanceof AppError)return 'Nepavyko. Bandykite dar kartą.';return ['INVALID_EMAIL'=>'Neteisingas el. pašto adresas.','INVALID_FIELD'=>'Patikrinkite laukelius.','RATE_LIMITED'=>'Per daug bandymų. Palaukite valandą.','CSRF_REQUIRED'=>'Puslapis paseno. Atnaujinkite jį ir bandykite dar kartą.','SAME_ORIGIN_REQUIRED'=>'Puslapis paseno. Atnaujinkite jį ir bandykite dar kartą.','CONFIG_WRITE_FAILED'=>'Nepavyko įrašyti nustatymų failo serveryje.'][$e->reason]??$e->reason;}
function staff_route(string $path,string $method):bool{
 if($path==='/admin/password'){
 // One-time link from the invitation email: the colleague chooses a password and is signed in.
 $raw=is_string($_GET['t']??null)&&preg_match('/^[a-f0-9]{64}$/',$_GET['t'])?$_GET['t']:'';$r=$raw?record('token:'.secret_hash($raw)):null;$email=$r&&($r['value']['kind']??'')==='staff-password'&&$r['expires_at']>time()?$r['value']['email']:null;$s=$email?record('staff:'.$email)['value']??null:null;
 if(!$s)staff_page('Nuoroda nebegalioja','<p>Ši nuoroda jau panaudota arba nebegalioja. Paprašykite administratoriaus atsiųsti naują.</p><p><a href="/admin/login">Prisijungti</a></p>');
 $error='';if($method==='POST'){try{csrf();db()->beginTransaction();rate('staff-password:'.($_SERVER['REMOTE_ADDR']??''),20,3600);$hash=staff_new_password();$s['hash']=$hash;$s['passwordSetAt']=now();put('staff:'.$email,'staff',$s);sql('DELETE FROM rb_records WHERE id=?',['token:'.secret_hash($raw)]);db()->commit();session_regenerate_id(true);$_SESSION['admin_until']=time()+28800;$_SESSION['admin_email']=$email;$_SESSION['admin_fingerprint']=secret_hash($hash);$_SESSION['csrf']=bin2hex(random_bytes(32));header('Location: /admin',true,303);exit;}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error=staff_error($e);}}
 staff_page('Susikurkite slaptažodį',($error?'<p class="error" role="alert">'.h($error).'</p>':'').'<p>Prisijungsite su el. paštu <strong>'.h($email).'</strong>.</p><form method="post"><input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'"><input type="email" name="email" value="'.h($email).'" autocomplete="username" hidden><label>Naujas slaptažodis (bent 14 simbolių)<input name="password" type="password" autocomplete="new-password" minlength="14" maxlength="72" required></label><label>Pakartokite slaptažodį<input name="password2" type="password" autocomplete="new-password" minlength="14" maxlength="72" required></label><button>Išsaugoti ir prisijungti</button></form>');
 }
 if($path!=='/admin/team')return false;
 if(!admin()){header('Location: /admin/login',true,303);exit;}
 $owner=is_owner();$me=admin_email();$c=config();$error='';$done='';$link='';
 if($method==='POST'){try{csrf();$do=$_POST['do']??'';db()->beginTransaction();
  if($do==='password'){$hash=staff_hash($me);if(!is_string($_POST['current']??null)||!$hash||!password_verify($_POST['current'],$hash))fail('Dabartinis slaptažodis neteisingas.');$new=staff_new_password();if($me===$c['admin_email'])staff_save_owner_hash($new);else{$s=record('staff:'.$me,true)['value'];$s['hash']=$new;$s['passwordSetAt']=now();put('staff:'.$me,'staff',$s);}$_SESSION['admin_fingerprint']=secret_hash($new);$done='Slaptažodis pakeistas.';}
  elseif(!$owner)fail('Kolegas pridėti ir šalinti gali tik pagrindinis administratorius.');
  elseif($do==='add'){$email=email($_POST['email']??null);$name=text($_POST['name']??'',0,60);if($email===$c['admin_email']||record('staff:'.$email))fail('Toks naudotojas jau yra.');$s=['email'=>$email,'name'=>$name,'hash'=>null,'addedAt'=>now(),'addedBy'=>$me,'passwordSetAt'=>null];put('staff:'.$email,'staff',$s);$link=staff_link($email);staff_invite_mail($s,$link,false);$done='Pridėta. Kvietimas išsiųstas adresu '.$email.'.';}
  elseif($do==='resend'||$do==='remove'){$email=email($_POST['email']??null);$r=record('staff:'.$email,true);if(!$r)fail('Naudotojas nerastas.');if($do==='remove'){if(($_POST['confirm']??'')!=='1')fail('Pažymėkite „Taip, pašalinti“.');sql("DELETE FROM rb_records WHERE id=? OR (kind='token' AND parent_id=?)",['staff:'.$email,'staff:'.$email]);$done=$email.' pašalintas. Jo prisijungimas nebegalioja.';}else{$link=staff_link($email);staff_invite_mail($r['value'],$link,$r['value']['hash']!==null);$done='Nauja nuoroda išsiųsta adresu '.$email.'.';}}
  else fail('INVALID_ACTION');
  db()->commit();if($link)dispatch_mail(3);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error=staff_error($e);$link='';$done='';}}
 $row=fn(string $name,string $email,string $status,string $tools='')=>'<div class="row"><div><strong>'.h($name!==''?$name:$email).'</strong>'.($name!==''?'<br><span class="muted">'.h($email).'</span>':'').'<br><span class="tag">'.h($status).'</span></div>'.$tools.'</div>';
 $form=fn(string $do,string $email,string $label,string $extra='',string $cls='secondary')=>'<form method="post" class="inline"><input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'"><input type="hidden" name="do" value="'.$do.'"><input type="hidden" name="email" value="'.h($email).'">'.$extra.'<button class="'.$cls.'">'.h($label).'</button></form>';
 $list=$row('',$c['admin_email'],'Pagrindinis administratorius'.($me===$c['admin_email']?' · tai jūs':''));
 foreach(records('staff') as $s)$list.=$row($s['name'],$s['email'],($s['hash']?'Aktyvus':'Laukia, kol susikurs slaptažodį').($me===$s['email']?' · tai jūs':''),$owner?'<div class="tools">'.$form('resend',$s['email'],$s['hash']?'Siųsti slaptažodžio keitimo nuorodą':'Siųsti kvietimą dar kartą').$form('remove',$s['email'],'Pašalinti','<label class="check"><input type="checkbox" name="confirm" value="1"> Taip, pašalinti</label>','danger').'</div>':'');
 $html=($error?'<p class="error" role="alert">'.h($error).'</p>':'').($done?'<p class="ok" role="status">'.h($done).'</p>':'').($link?'<p class="muted">Jei laiškas neateitų, nusiųskite šią nuorodą kolegai patys (galioja '.STAFF_LINK_HOURS.' val., tinka vieną kartą):</p><input readonly value="'.h($link).'">':'')
 .'<p>Šie žmonės gali prisijungti prie administravimo ir matyti visus užsakymus.</p><div class="list">'.$list.'</div>'
 .($owner?'<h2>Pridėti kolegą</h2><p class="muted">Kolegai išsiųsime laišką su nuoroda. Joje jis susikurs savo slaptažodį ir galės prisijungti su savo el. paštu.</p><form method="post"><input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'"><input type="hidden" name="do" value="add"><label>Vardas<input name="name" maxlength="60" autocomplete="off"></label><label>El. paštas<input name="email" type="email" required autocomplete="off"></label><button>Pridėti ir išsiųsti kvietimą</button></form>':'')
 .'<h2>Mano slaptažodis</h2><form method="post"><input type="hidden" name="csrf" value="'.h($_SESSION['csrf']).'"><input type="hidden" name="do" value="password"><input type="email" name="email" value="'.h($me).'" autocomplete="username" hidden><label>Dabartinis slaptažodis<input name="current" type="password" autocomplete="current-password" required maxlength="72"></label><label>Naujas slaptažodis (bent 14 simbolių)<input name="password" type="password" autocomplete="new-password" minlength="14" maxlength="72" required></label><label>Pakartokite naują slaptažodį<input name="password2" type="password" autocomplete="new-password" minlength="14" maxlength="72" required></label><button class="secondary">Pakeisti slaptažodį</button></form>'
 .'<p class="back"><a href="/admin">← Atgal į administravimą</a></p>';
 staff_page('Komanda',$html);
}
